//#region src/ast-transform/transforms/transform-arrow-function-expression.ts
const commonProperties = {
	id: null,
	generator: false,
	async: false,
	expression: true
};
const visitArrowFunction = (node, transformer) => ({
	type: "ArrowFunctionExpression",
	params: node.parameters.map((parameter) => transformer.createNode({
		type: "Identifier",
		name: parameter.name
	}, parameter.sourceSpan)),
	body: transformer.transformChild(node.body),
	...commonProperties
});

//#endregion
export { visitArrowFunction };

