# Full `printFunctionParameters` Function

```js
function printFunctionParameters(
  path,
  options,
  print,
  shouldExpandParameters,
  shouldPrintTypeParameters,
) {
  const functionNode = path.node;
  const parameters = getFunctionParameters(functionNode);
  const typeParametersDoc =
    shouldPrintTypeParameters && functionNode.typeParameters
      ? print("typeParameters")
      : "";

  if (parameters.length === 0) {
    return [
      typeParametersDoc,
      "(",
      printDanglingCommentsInList(
        path,
        options,
        functionParameterDanglingCommentFilter,
      ),
      ")",
    ];
  }

  const { parent } = path;
  const isParametersInTestCall = isTestCall(parent);
  const shouldHugParameters = shouldHugTheOnlyFunctionParameter(functionNode);
  const printed = [];
  iterateFunctionParametersPath(path, (parameterPath, index) => {
    const isLastParameter = index === parameters.length - 1;
    if (isLastParameter && functionNode.rest) {
      printed.push("...");
    }
    printed.push(print());
    if (isLastParameter) {
      return;
    }
    printed.push(",");
    if (isParametersInTestCall || shouldHugParameters) {
      printed.push(" ");
    } else if (isNextLineEmpty(parameters[index], options)) {
      printed.push(hardline, hardline);
    } else {
      printed.push(line);
    }
  });

  if (shouldExpandParameters && !isDecoratedFunction(path)) {
    if (willBreak(typeParametersDoc) || willBreak(printed)) {
      throw new ArgExpansionBailout();
    }
    return group([
      removeLines(typeParametersDoc),
      "(",
      removeLines(printed),
      ")",
    ]);
  }

  const hasNotParameterDecorator = parameters.every(
    (node) => !isNonEmptyArray(node.decorators),
  );
  if (shouldHugParameters && hasNotParameterDecorator) {
    return [typeParametersDoc, "(", ...printed, ")"];
  }

  if (isParametersInTestCall) {
    return [typeParametersDoc, "(", ...printed, ")"];
  }

  const isFlowShorthandWithOneArg =
    (isFlowObjectTypePropertyAFunction(parent) ||
      isTypeAnnotationAFunction(parent) ||
      parent.type === "TypeAlias" ||
      parent.type === "UnionTypeAnnotation" ||
      parent.type === "IntersectionTypeAnnotation" ||
      (parent.type === "FunctionTypeAnnotation" &&
        parent.returnType === functionNode)) &&
    parameters.length === 1 &&
    parameters[0].name === null &&
    functionNode.this !== parameters[0] &&
    parameters[0].typeAnnotation &&
    functionNode.typeParameters === null &&
    isSimpleType(parameters[0].typeAnnotation) &&
    !functionNode.rest;

  if (isFlowShorthandWithOneArg) {
    if (
      options.arrowParens === "always" ||
      functionNode.type === "HookTypeAnnotation"
    ) {
      return ["(", ...printed, ")"];
    }
    return printed;
  }

  return [
    typeParametersDoc,
    "(",
    indent([softline, ...printed]),
    !hasRestParameter(functionNode) &&
    path.root.type !== "NGRoot"
      ? printTrailingComma(options, "all")
      : "",
    softline,
    ")",
  ];
}
```

# Trailing Comma Decision (Exact Lines)

The trailing comma is decided in the final return statement. The precise condition:

```js
    !hasRestParameter(functionNode) &&
    // Angular does not allow trailing comma
    path.root.type !== "NGRoot"
      ? printTrailingComma(options, "all")
      : "",
```

This suppresses the trailing comma when the function has a rest parameter **or** when the root node is an Angular (`NGRoot`) tree; otherwise it calls `printTrailingComma`.

# Angular-Related Code

Only one Angular reference exists—the check above. Its accompanying comment states: `// Angular does not allow trailing comma`.

